package com.opensocket.aievent.core.issuetracking.core;
import static org.junit.jupiter.api.Assertions.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import com.opensocket.aievent.core.issuetracking.relay.*;
class RelayTopologyAggregateCalculatorTest { @Test void independentEdgesProducePartialWithoutRollback(){var calc=new RelayTopologyAggregateCalculator();assertEquals(RelayTopologyStatus.PARTIAL,calc.calculate(List.of(edge("a",RelayEdgeStatus.SYNCED,""),edge("b",RelayEdgeStatus.FAILED_PERMANENT,"X"))));} @Test void unsupportedNativeRelationRequiresDecision(){var calc=new RelayTopologyAggregateCalculator();assertEquals(RelayTopologyStatus.DECISION_REQUIRED,calc.calculate(List.of(edge("a",RelayEdgeStatus.FAILED_PERMANENT,"PROVIDER_NATIVE_RELATION_UNSUPPORTED"))));}
 private RelayEdge edge(String id,RelayEdgeStatus status,String code){var now=OffsetDateTime.now(ZoneOffset.UTC);return new RelayEdge("t",id,"top","c","m","JIRA","p","A","B",RelayEdgeType.PROVIDER_NATIVE_RELATION,"RELATES_TO","marker",status,1,null,"",code,"",1,now,now,"");}}
